'use strict'
const {app,BrowserWindow,ipcMain,session}=require('electron'),{build}=require('esbuild'),fs=require('node:fs'),path=require('node:path'),{pathToFileURL}=require('node:url')
const root=path.resolve(__dirname,'../..'),output=path.join(root,'qa-artifacts/agent-team');fs.mkdirSync(output,{recursive:true});app.setPath('userData',fs.mkdtempSync(path.join(output,'profile-')));app.disableHardwareAcceleration()
let win,store
async function main(){
 await app.whenReady();const {StableStore}=require('../../desktop/services/store.cjs'),{SkillMarket}=require('../../desktop/services/skill-market.cjs');store=new StableStore(app.getPath('userData'));const market=new SkillMarket(store,app.getPath('userData'))
 for(const method of ['list','detail','toggle','remove','use'])ipcMain.handle('expert-test:'+method,(_e,...args)=>method==='list'?market.entries():method==='use'?{activeConversationId:market.use(...args)}:market[method](...args))
 session.defaultSession.webRequest.onBeforeRequest((details,callback)=>callback({cancel:/^https?:/.test(details.url)}))
 win=new BrowserWindow({show:false,width:1500,height:1100,webPreferences:{offscreen:true,sandbox:true,preload:path.join(__dirname,'expert-market-preload.cjs')}})
 const bundle=(await build({stdin:{contents:`import React from 'react';import {createRoot} from 'react-dom/client';import {SkillMarket} from './src/SkillMarket';createRoot(document.getElementById('root')).render(<SkillMarket onUse={state=>window.usedState=state} renderContent={content=><pre style={{whiteSpace:'pre-wrap',fontFamily:'inherit',fontSize:14}}>{content}</pre>}/>);`,resolveDir:root,loader:'tsx'},bundle:true,write:false,format:'iife',define:{'process.env.NODE_ENV':'"production"','import.meta.env.BASE_URL':JSON.stringify(pathToFileURL(path.join(root,'public')).href+'/')}})).outputFiles[0].text
 const html=path.join(output,'index.html');fs.writeFileSync(html,'<html data-theme="light"><meta charset="utf-8"><body style="margin:0"><div id="root" style="height:100vh"></div></body></html>')
 await win.loadFile(html);for(const file of ['tokens.css','app.css'])await win.webContents.insertCSS(fs.readFileSync(path.join(root,'src/styles',file),'utf8'));await win.webContents.executeJavaScript(bundle)
 const run=script=>win.webContents.executeJavaScript(`(async()=>{const tick=()=>new Promise(r=>setTimeout(r,120)),expect=(value,message)=>{if(!value)throw Error(message)},click=text=>{const b=[...document.querySelectorAll('button')].find(b=>b.textContent===text);expect(b,'Missing '+text);b.click()};${script}})()`)
 await run(`await tick();click('Agent专家');await tick();expect(document.querySelectorAll('.market-row').length===444,'Catalogue count');expect(getComputedStyle(document.querySelector('.market-grid')).gridTemplateColumns.split(' ').length===3,'Three columns');`)
 await new Promise(r=>setTimeout(r,800));await run(`expect([...document.querySelectorAll('.market-avatar img')].slice(0,12).every(img=>img.complete&&img.naturalWidth>0),'Offline avatars');expect(document.documentElement.scrollWidth<=innerWidth,'Horizontal overflow');`)
 fs.writeFileSync(path.join(output,'expert-market.png'),(await win.webContents.capturePage()).toPNG());fs.writeFileSync(path.join(output,'expert-market.jpg'),(await win.webContents.capturePage()).toJPEG(65))
 await run(`expect(!document.querySelector('[aria-label="专家来源"]'),'Source selector should be removed');const input=document.querySelector('.market-search input');Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,'value').set.call(input,'数据分析师');input.dispatchEvent(new Event('input',{bubbles:true}));await tick();expect(document.querySelectorAll('.market-row').length>=3,'Search results');document.querySelector('.market-row-copy').click();await tick();expect(document.querySelector('dialog').open,'Details open');expect(document.querySelectorAll('[aria-label="专家设定文件"] option').length===3,'Three persona files');expect(document.querySelector('.market-detail-body').textContent.includes('IDENTITY.md'),'Identity content');const docs=document.querySelector('[aria-label="专家设定文件"]');docs.value='2';docs.dispatchEvent(new Event('change',{bubbles:true}));await tick();expect(document.querySelector('.market-detail-body').textContent.includes('经营诊断硬门'),'Full AGENTS content');expect(!/work.buddy|workbuddy|codebuddy|doubao|豆包/i.test(document.querySelector('dialog').textContent),'Platform names in expert detail');click('依赖说明');await tick();expect(!/work.buddy|workbuddy|codebuddy|doubao|豆包/i.test(document.querySelector('dialog').textContent),'Platform names in dependencies');click('专家设定');await tick();click('添加专家');await tick();expect(document.querySelector('dialog .primary').textContent==='在对话中试用','Added state');click('在对话中试用');await tick();expect(window.usedState?.activeConversationId,'Conversation dispatch');`)
 fs.writeFileSync(path.join(output,'expert-detail.png'),(await win.webContents.capturePage()).toPNG());fs.writeFileSync(path.join(output,'expert-detail.jpg'),(await win.webContents.capturePage()).toJPEG(65))
 await run(`document.querySelector('.market-dialog-close').click();document.querySelector('.market-mine-toggle').click();await tick();expect(document.querySelectorAll('.market-row').length===1,'My experts');document.querySelector('.market-row-copy').click();await tick();document.querySelector('.market-more summary').click();click('从我的专家移除');await tick();expect(document.querySelectorAll('.market-row').length===0,'Remove from mine');document.querySelector('.market-mine-toggle').click();await tick();expect(document.querySelectorAll('.market-row').length===444,'Catalogue still present');`)
 await run(`const input=document.querySelector('.market-search input');Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,'value').set.call(input,'内容创作专家');input.dispatchEvent(new Event('input',{bubbles:true}));await tick();document.querySelector('.market-row-copy').click();await tick();expect(!/work.buddy|workbuddy|codebuddy|doubao|豆包/i.test(document.querySelector('dialog').textContent),'Platform names in content creator');expect(!document.querySelector('.expert-provenance'),'Source attribution row still visible');document.querySelector('.market-dialog-close').click();`)
 win.setSize(900,1000);await run(`await tick();expect(getComputedStyle(document.querySelector('.market-grid')).gridTemplateColumns.split(' ').length===2,'Two-column responsive');`)
 win.setSize(600,1000);await run(`await tick();expect(getComputedStyle(document.querySelector('.market-grid')).gridTemplateColumns.split(' ').length===1,'One-column responsive: viewport='+innerWidth+', container='+document.querySelector('.expert-market').clientWidth+', columns='+getComputedStyle(document.querySelector('.market-grid')).gridTemplateColumns);expect(document.documentElement.scrollWidth<=innerWidth,'Narrow overflow');`)
 fs.writeFileSync(path.join(output,'expert-market-narrow.png'),(await win.webContents.capturePage()).toPNG())
 console.log('EXPERT_MARKET_UI_PASSED');win.destroy();store.close();app.exit(0)
}
main().catch(error=>{console.error(error.stack);win?.destroy();store?.close();app.exit(1)})
